import React from 'react';
import styles from './Sidebar.module.css';
import { useNavigation } from '../context/NavigationContext';

const Sidebar = () => {
  const { setCurrentPage } = useNavigation();

  return (
    <aside className={styles.sidebar}>
      <nav>
        <ul className={styles.navList}>
          {/* Home */}
          <li 
            className={styles.navItem}
            onClick={() => console.log('Home clicked')} // Platzhalter
          >
            <span>🏠</span>
            <span>Home</span>
          </li>

          {/* Dashboard (aktiver Link) */}
          <li 
            className={`${styles.navItem} ${styles.active}`}
            onClick={() => setCurrentPage('dashboard')}
          >
            <span>📊</span>
            <span>Dashboard</span>
          </li>

          {/* Users */}
          <li 
            className={styles.navItem}
            onClick={() => console.log('Users clicked')} // Platzhalter
          >
            <span>👥</span>
            <span>Users</span>
          </li>

          {/* Analytics */}
          <li 
            className={styles.navItem}
            onClick={() => console.log('Analytics clicked')} // Platzhalter
          >
            <span>📈</span>
            <span>Analytics</span>
          </li>
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
